import re

class Parser:
    def __init__(self, text):
        # Names have several characters, so split the text into tokens first.
        self.tokens = re.findall(r"\d+|[A-Za-z_]\w*|\S", text)
        self.pos = 0
        self.vars = {}                      # the symbol table: name -> value

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def match(self, token):
        if self.peek() == token:
            self.pos += 1
            return True
        return False

    def E(self):
        value = self.T()
        while self.peek() in ("+", "-"):
            op = self.peek()
            self.match(op)
            right = self.T()
            value = value + right if op == "+" else value - right
        return value

    def T(self):
        value = self.F()
        while self.peek() in ("*", "/"):
            op = self.peek()
            self.match(op)
            right = self.F()
            value = value * right if op == "*" else value / right
        return value

    def F(self):
        token = self.peek()
        if self.match("("):
            value = self.E()
            self.match(")")
            return value
        self.match(token)
        if token.isdigit():
            return int(token)
        return self.vars[token]             # lookup: read the name's value

    def statement(self):
        token = self.peek()
        self.match(token)
        if token == "print":
            print(self.E())
        else:
            self.match("=")
            self.vars[token] = self.E()     # assignment: store the value
        self.match(";")

    def parse(self):
        while self.peek() is not None:
            self.statement()


Parser("x = 3; x = x + 4; print x * 2;").parse()      # 14

